// ManagerServiceServer is the server API for ManagerService service.
// All implementations must embed UnimplementedManagerServiceServer
// for forward compatibility.
//
// ManagerService is the external RPC API exposed by managerd.
// CreateVM/UpdateVM/DeleteVM record ephemeral VM definitions via raftd -
// there is still no bhyve/jail/zfs backend, so nothing actually runs a VM
// yet, but the definitions are real, replicated, and persisted.
type ManagerServiceServer interface {
	Status(context.Context, *StatusRequest) (*StatusResponse, error)
	CreateVM(context.Context, *CreateVMRequest) (*CreateVMResponse, error)
	UpdateVM(context.Context, *UpdateVMRequest) (*UpdateVMResponse, error)
	DeleteVM(context.Context, *DeleteVMRequest) (*DeleteVMResponse, error)
	// ForcePurgeVM is an escape hatch for a VM tombstoned by DeleteVM
	// whose owning node will never reconcile it away (permanently
	// offline/decommissioned) - see CLAUDE.md's "What's not implemented
	// yet" note on resource reclaim. It only succeeds against a VM
	// already in VM_STATE_DELETING (call DeleteVM first) and removes the
	// record outright, the same way the owning node's own reconciler
	// would via PurgeVM - but it does NOT touch that node's real ZFS
	// dataset or bhyve VM, since (by definition, this being needed at
	// all) that node can't be reached. Use only when the owning node is
	// confirmed gone for good; otherwise its resources are silently
	// orphaned with no record left to indicate they exist.
	ForcePurgeVM(context.Context, *ForcePurgeVMRequest) (*ForcePurgeVMResponse, error)
	// MigrateVM is a manual, explicit, human-triggered operation moving
	// a VM's ownership to target_node_id - Apiary has no automatic
	// scheduling (CLAUDE.md's deliberate stance), so this exists purely
	// to fill the "there's no way to move a VM at all" gap, not to add
	// scheduling logic. It only succeeds when target_node_id is already
	// this VM's replica_node_id - i.e., a HAST secondary already holding
	// a synced copy of the disk (see ADR-0026/ADR-0028) - since for any
	// other target, the VM's disk isn't present there at all: the
	// reconciler would tear down the real disk on the old node
	// (ADR-0025's resource reclaim) and provision a brand-new EMPTY one
	// on the new node, silently destroying the VM's actual data. This
	// isn't a technical limitation to remove later - it's the same
	// "never allow a silently destructive default" caution this
	// project has applied everywhere else. To migrate a VM with no
	// existing replica: set replica_node_id via UpdateVM first, confirm
	// real replication has reached hastctl's own "status: complete" on
	// the target, then call MigrateVM.
	//
	// On success, node_id and replica_node_id are swapped (the old
	// owner becomes the new secondary, continuing replication back) -
	// the reconciler's existing HAST role machinery converges this
	// exactly like any other role change, no new reconciler logic
	// involved.
	MigrateVM(context.Context, *MigrateVMRequest) (*MigrateVMResponse, error)
	// GetVM and ListVMs only succeed against the current leader - see
	// api/internalpb/raftd.proto's GetVM/ListVMs doc comments for why v1's
	// read consistency model is deliberately as simple as its write model.
	GetVM(context.Context, *GetVMRequest) (*GetVMResponse, error)
	ListVMs(context.Context, *ListVMsRequest) (*ListVMsResponse, error)
	// UploadISO, ListISOs, and DeleteISO manage installer images stored
	// locally on *this* managerd's own node - unlike VM definitions,
	// these are physical data (see CLAUDE.md's physical/ephemeral
	// distinction) and are never replicated through raft. UploadISO is
	// client-streaming so a large image doesn't have to fit in one
	// message; see ADR-0017 for why verification happens server-side
	// rather than trusting a client-computed hash.
	UploadISO(grpc.ClientStreamingServer[UploadISORequest, UploadISOResponse]) error
	ListISOs(context.Context, *ListISOsRequest) (*ListISOsResponse, error)
	DeleteISO(context.Context, *DeleteISORequest) (*DeleteISOResponse, error)
	// HostStats reports a point-in-time snapshot of *this* node's own
	// resource usage and hardware health - physical, per-node data like
	// ISOs above, gathered locally by managerd (see internal/hoststats),
	// never routed through raft.
	HostStats(context.Context, *HostStatsRequest) (*HostStatsResponse, error)
	// GetVMConsole reports how to reach a running VM's VNC framebuffer,
	// for the web UI's noVNC-based console page (ADR-0020). Like HostStats,
	// this only answers for a VM actually running on *this* node - see
	// GetVMConsoleResponse's doc comment for the v1 limitation that
	// follows from that.
	GetVMConsole(context.Context, *GetVMConsoleRequest) (*GetVMConsoleResponse, error)
	// GetVMSerialLog returns the tail of a VM's captured serial console
	// log (ADR-0032's EnableSerialLog), for the web UI - previously this
	// required an operator to read the file directly on the owning node.
	// Same locality limitation as GetVMConsole: only answers for a VM
	// confirmed running on *this* node.
	GetVMSerialLog(context.Context, *GetVMSerialLogRequest) (*GetVMSerialLogResponse, error)
	// CreateNetwork/ListNetworks/DeleteNetwork manage NetworkDefinitions -
	// VLAN/subnet/bridge segments a VM can attach to (see ADR-0022).
	// CreateNetwork/DeleteNetwork just submit a Command through raft
	// (like CreateVM/DeleteVM); ListNetworks reads current state, subject
	// to the same leader-only requirement as ListVMs.
	CreateNetwork(context.Context, *CreateNetworkRequest) (*CreateNetworkResponse, error)
	ListNetworks(context.Context, *ListNetworksRequest) (*ListNetworksResponse, error)
	DeleteNetwork(context.Context, *DeleteNetworkRequest) (*DeleteNetworkResponse, error)
	// CreateAPIKey/ListAPIKeys/RevokeAPIKey manage credentials for this
	// service's own RPC surface (ADR-0023). CreateAPIKey is the only
	// place a raw key is ever returned - it cannot be retrieved again
	// after this response. Once at least one key exists, every RPC on
	// this service (including these three) requires a valid one; before
	// that, everything remains open, matching this project's behavior
	// today.
	CreateAPIKey(context.Context, *CreateAPIKeyRequest) (*CreateAPIKeyResponse, error)
	ListAPIKeys(context.Context, *ListAPIKeysRequest) (*ListAPIKeysResponse, error)
	RevokeAPIKey(context.Context, *RevokeAPIKeyRequest) (*RevokeAPIKeyResponse, error)
	// CreateJail/UpdateJail/DeleteJail/GetJail/ListJails manage
	// JailDefinitions - see ADR-0026's jail-orchestration half. They
	// mirror the VM RPCs above exactly, including GetJail/ListJails'
	// same leader-only read requirement.
	CreateJail(context.Context, *CreateJailRequest) (*CreateJailResponse, error)
	UpdateJail(context.Context, *UpdateJailRequest) (*UpdateJailResponse, error)
	DeleteJail(context.Context, *DeleteJailRequest) (*DeleteJailResponse, error)
	GetJail(context.Context, *GetJailRequest) (*GetJailResponse, error)
	ListJails(context.Context, *ListJailsRequest) (*ListJailsResponse, error)
	// ForcePurgeJail mirrors ForcePurgeVM exactly, for a jail tombstoned
	// by DeleteJail whose owning node will never come back to reconcile
	// it away. See ForcePurgeVM's own doc comment above for the full
	// reasoning - it applies identically here.
	ForcePurgeJail(context.Context, *ForcePurgeJailRequest) (*ForcePurgeJailResponse, error)
	// MigrateJail mirrors MigrateVM exactly, for jails instead of VMs -
	// see MigrateVM's own doc comment above for the full reasoning
	// (including the "target must already be a synced HAST replica"
	// safety requirement), which applies identically here.
	MigrateJail(context.Context, *MigrateJailRequest) (*MigrateJailResponse, error)
	// ReportVMPhase/ReportVMTeardownComplete/ReportJailPhase/
	// ReportJailTeardownComplete are peer-to-peer RPCs, not meant for
	// human/API-client use: a reconciler on a node that owns a VM/jail
	// but whose own raftd isn't the current raft leader calls these on
	// the LEADER node's managerd instead, since only the leader's own
	// raftd can ever accept an Apply (ADR-0029) - raftd's internal API
	// stays Unix-socket-only, never exposed over the network; this
	// reuses ManagerService's existing, already-networked, already-
	// optionally-API-key-gated external surface instead of opening a
	// new one. Gated by the same auth as every other RPC here when
	// enabled - see cmd/managerd's -peer-api-key flag.
	ReportVMPhase(context.Context, *ReportVMPhaseRequest) (*ReportVMPhaseResponse, error)
	ReportVMTeardownComplete(context.Context, *ReportVMTeardownCompleteRequest) (*ReportVMTeardownCompleteResponse, error)
	ReportJailPhase(context.Context, *ReportJailPhaseRequest) (*ReportJailPhaseResponse, error)
	ReportJailTeardownComplete(context.Context, *ReportJailTeardownCompleteRequest) (*ReportJailTeardownCompleteResponse, error)
	mustEmbedUnimplementedManagerServiceServer()
}

